/* --- XP / Soul Pool thresholds (PLACEHOLDER curve — Luke can retune) ------------------------------
   The Soul Pool IS your cumulative XP. Advancing from level L to L+1 costs 100 × L² XP, so the total
   XP needed to REACH level L is the running sum below. Early levels are quick; high levels grind.
   To retune later, change PC.XP_STEP (or replace PC.XP_THRESHOLDS wholesale) — everything downstream
   (level-for-xp, the progress bar, "ready to level") derives from this one table. */
PC.XP_STEP = function (level) { return 100 * level * level; }; // XP cost to go from `level` → level+1
PC.XP_THRESHOLDS = (function () {
  const out = [0, 0]; // index by Soul Level; L1 needs 0 total XP (out[0] unused)
  for (let L = 2; L <= PC.RULES.LEVEL_CAP; L++) out[L] = out[L - 1] + PC.XP_STEP(L - 1);
  return out; // out[L] = total XP required to be at level L
})();

